import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box, Button, Chip, Paper, TextField, Typography, useMediaQuery } from '@mui/material';
import { useSearchParams } from 'react-router-dom';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { DEMO_VENUES, type VenuePerson } from '../data/venues';
import { loadFriends } from '../utils/friends';
import { liveAiStatus, type LiveAiStatus } from '../utils/liveAi';
import { elementColor, elementEmoji, resolveNavitarArt } from '../utils/navitarArt';
import {
  SOCIAL_CHANGED_EVENT,
  GROUP_CHAT_REPLIES,
  groupUnreadCount,
  loadGroupLastRead,
  loadSocial,
  markGroupRead,
  migrateGroupReadState,
  saveSocial,
  type DemoGroup,
} from '../utils/social';
import {
  REPLY_DELAY_MS,
  THREADS_CHANGED_EVENT,
  appendMessage,
  ensureNavitarThread,
  ensurePersonThread,
  getThread,
  getThreadReply,
  loadThreads,
  markThreadRead,
  migrateThreadReadState,
  sortThreadsByRecent,
  threadUnreadCount,
  type Thread,
  type ThreadMessage,
} from '../utils/threads';
import { NavitarArtImg } from '../components/NavitarArtImg';

// The Inbox (Round 22, Eddie 2026-11-18) — the ONE home for
// conversations. This page used to be "Messages"; Eddie's order
// made it an inbox in the phone sense: every conversation lives
// here (1:1 threads with the people you've met, your navitar's
// thread, and your group chats from Friends & Groups), each row
// badged with its unread count — and the words themselves live
// ONLY here.
//
// Eddie's type-only law, enforced on this page too: a row's
// preview line says the TYPE of the last activity ("💬 New
// message", "💬 You sent a message") — never the message text.
// The text renders only inside the open conversation. The same
// law governs the notification store (utils/notifications.ts):
// a message notification is type + sender, full stop.
//
// Stores (no parallel universe — the inbox is a view over the
// real state): 1:1 + navitar threads in glacer-threads
// (utils/threads.ts, shared with Profile's NavitarChat), group
// chats in glacer-social-demo (utils/social.ts, shared with the
// Friends page — both doors write the same store and answer
// from the same reply bank). Read state: threads carry
// lastReadAt; groups use the glacer-group-last-read side map.
// Local-only demo layer, like the rest: person threads are with
// the game's demo people, replies are scripted (or DeepSeek when
// Live AI is on with a key — always via getThreadReply).

const REPLY_MODE_CAPTION: Record<LiveAiStatus, string> = {
  off: 'Replies are scripted — Live AI is off.',
  'on-no-key': 'Live AI is on but no DeepSeek key is configured — replies are scripted.',
  ready: 'Live AI is on — replies come from DeepSeek.',
};

// Group replies pause a beat, like the Friends page's group chat.
const GROUP_REPLY_DELAY_MS = 1000;

function formatTime(ts: number): string {
  return new Date(ts).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

// A demo person, resolved against DEMO_VENUES by person id — the same
// resolution Profile uses for its friends list.
function findPerson(personId: string): VenuePerson | null {
  for (const venue of DEMO_VENUES) {
    const person = venue.people.find(p => p.id === personId);
    if (person) return person;
  }
  return null;
}

// Avatar for a thread or friend row: the navitar art when it resolves,
// otherwise the element emoji in an element-coloured circle — the same
// pattern as Profile's friend cards.
function ThreadAvatar({
  title,
  navitarName,
  navitarImage,
  element,
  size,
}: {
  title: string;
  navitarName?: string;
  navitarImage?: string;
  element?: string;
  size: number;
}) {
  const art = resolveNavitarArt(navitarImage, navitarName ?? title);
  if (art) {
    return (
      <NavitarArtImg
        src={art}
        alt={`${title} art`}
        element={element ?? 'ice'}
        style={{
          width: size,
          height: size,
          borderRadius: '50%',
          border: `2px solid ${elementColor(element ?? 'ice')}`,
          flexShrink: 0,
        }}
      />
    );
  }
  return (
    <Box
      sx={{
        width: size,
        height: size,
        borderRadius: '50%',
        border: `2px solid ${elementColor(element ?? 'ice')}`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '1.5rem',
        flexShrink: 0,
      }}
    >
      {elementEmoji(element ?? 'ice')}
    </Box>
  );
}

function GroupAvatar({ size }: { size: number }) {
  return (
    <Box
      sx={{
        width: size,
        height: size,
        borderRadius: '50%',
        border: '2px solid rgba(232,145,45,0.8)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '1.5rem',
        flexShrink: 0,
      }}
    >
      👥
    </Box>
  );
}

// One row of the inbox list: a thread, a group chat, or a friend
// with no thread yet (opening it says hello first — no history is
// fabricated). `preview` is ALWAYS a type-level line, never text.
interface ListRow {
  key: string;
  threadId: string | null;
  groupId: string | null;
  person: VenuePerson | null;
  title: string;
  subtitle: string;
  navitarName?: string;
  navitarImage?: string;
  element?: string;
  preview: string;
  previewTs: number | null;
  sayHello: boolean;
  unread: number;
  demo: boolean;
  sortTs: number;
}

const Messages: React.FC = () => {
  const { userNavitar } = useNavitarFightClub();
  const [searchParams, setSearchParams] = useSearchParams();
  const isDesktop = useMediaQuery('(min-width:900px)');
  const [threads, setThreads] = useState<Thread[]>(() => sortThreadsByRecent(loadThreads()));
  const [groups, setGroups] = useState<DemoGroup[]>(() => loadSocial().groups.filter(g => !g.left));
  const [groupReadMap, setGroupReadMap] = useState<Record<string, number>>(() =>
    loadGroupLastRead()
  );
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedGroupId, setSelectedGroupId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ThreadMessage[]>([]);
  const [input, setInput] = useState('');
  const [groupInput, setGroupInput] = useState('');
  const [typingThreadId, setTypingThreadId] = useState<string | null>(null);
  const [typingGroupId, setTypingGroupId] = useState<string | null>(null);
  const [liveAiUnavailable, setLiveAiUnavailable] = useState(false);
  const mountedRef = useRef(true);
  const timeoutRef = useRef<number | null>(null);
  const groupTimeoutRef = useRef<number | null>(null);
  const messagesRef = useRef<HTMLDivElement | null>(null);
  const groupMessagesRef = useRef<HTMLDivElement | null>(null);
  const selectedIdRef = useRef<string | null>(null);
  selectedIdRef.current = selectedId;
  const selectedGroupIdRef = useRef<string | null>(null);
  selectedGroupIdRef.current = selectedGroupId;
  // The reply-mode caption is read at render; the toggle lives on
  // Profile, so it cannot change while this page is open.
  const replyMode = liveAiStatus();

  const refreshThreads = () => setThreads(sortThreadsByRecent(loadThreads()));
  const refreshGroups = () => {
    setGroups(loadSocial().groups.filter(g => !g.left));
    setGroupReadMap(loadGroupLastRead());
  };
  const refreshAll = () => {
    refreshThreads();
    refreshGroups();
  };

  // Mount: read-state migration (legacy history starts read), the
  // navitar always has a thread row, the list reflects the stores,
  // and a ?thread=<id> / ?group=<id> deep-link selects that
  // conversation when it exists. A deep-link naming something that
  // does not exist is ignored, not a crash.
  useEffect(() => {
    migrateThreadReadState();
    migrateGroupReadState(loadSocial().groups);
    if (userNavitar) {
      ensureNavitarThread({
        id: userNavitar.id,
        name: userNavitar.name,
        element: userNavitar.element,
        imageUrl: userNavitar.imageUrl,
      });
    }
    refreshAll();
    const deepLinkId = searchParams.get('thread');
    if (deepLinkId && getThread(deepLinkId)) {
      setSelectedId(deepLinkId);
      setMessages(getThread(deepLinkId)?.messages ?? []);
      markThreadRead(deepLinkId);
      refreshThreads();
      return;
    }
    const deepGroupId = searchParams.get('group');
    if (deepGroupId && loadSocial().groups.some(g => g.id === deepGroupId && !g.left)) {
      setSelectedGroupId(deepGroupId);
      markGroupRead(deepGroupId);
      refreshGroups();
    }
    // Mount-only on purpose: the navitar thread is seeded once, and
    // the deep-link is read once. (No eslint-disable here: this repo's
    // config has no eslint-plugin-react-hooks, so naming the rule
    // errors the build.)
  }, []);

  // Live arrivals: a message appended anywhere (the incoming
  // producer while the player was elsewhere, a reply landing from
  // Profile's NavitarChat, a group reply from the Friends page)
  // refreshes the list — and the open conversation, which counts
  // as read because the player is looking at it.
  useEffect(() => {
    const onChange = () => {
      refreshAll();
      const openThread = selectedIdRef.current;
      if (openThread) {
        const t = getThread(openThread);
        if (t) {
          setMessages(t.messages);
          if (threadUnreadCount(t) > 0) {
            markThreadRead(openThread);
            refreshThreads();
          }
        }
      }
      const openGroup = selectedGroupIdRef.current;
      if (openGroup) {
        const g = loadSocial().groups.find(x => x.id === openGroup);
        if (g && groupUnreadCount(g, loadGroupLastRead()) > 0) {
          markGroupRead(openGroup);
          refreshGroups();
        }
      }
    };
    window.addEventListener(THREADS_CHANGED_EVENT, onChange);
    window.addEventListener(SOCIAL_CHANGED_EVENT, onChange);
    window.addEventListener('storage', onChange);
    return () => {
      window.removeEventListener(THREADS_CHANGED_EVENT, onChange);
      window.removeEventListener(SOCIAL_CHANGED_EVENT, onChange);
      window.removeEventListener('storage', onChange);
    };
  }, []);

  // Guard the delayed replies against unmount — no setState after
  // the page is gone, and the pending timeouts are cleared.
  useEffect(
    () => () => {
      mountedRef.current = false;
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current);
      if (groupTimeoutRef.current !== null) window.clearTimeout(groupTimeoutRef.current);
    },
    []
  );

  // Auto-scroll the open conversation to the bottom on new messages.
  const selectedGroup = groups.find(g => g.id === selectedGroupId) ?? null;
  const groupMessages = selectedGroup?.messages ?? [];
  useEffect(() => {
    const el = messagesRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [messages.length]);
  useEffect(() => {
    const el = groupMessagesRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [groupMessages.length]);

  // Friends (resolved against DEMO_VENUES, like Profile) with no
  // thread yet — they still get a row, with a "Say hello" preview.
  const friendRows: ListRow[] = useMemo(() => {
    const threadPersonIds = new Set(
      threads.filter(t => t.kind === 'person' && t.personId).map(t => t.personId as string)
    );
    return loadFriends()
      .map((personId): VenuePerson | null => findPerson(personId))
      .filter((p): p is VenuePerson => p !== null)
      .filter(p => !threadPersonIds.has(p.id))
      .map((person): ListRow => ({
        key: `friend-${person.id}`,
        threadId: null,
        groupId: null,
        person,
        title: person.name,
        subtitle: `${person.navitarName} · Lv. ${person.navitarLevel} · ${person.navitarElement}`,
        navitarName: person.navitarName,
        navitarImage: person.navitarImage,
        element: person.navitarElement,
        preview: 'Say hello',
        previewTs: null,
        sayHello: true,
        unread: 0,
        demo: true,
        sortTs: 0,
      }));
  }, [threads]);

  const threadRows: ListRow[] = useMemo(
    () =>
      threads.map((thread): ListRow => {
        const person = thread.personId ? findPerson(thread.personId) : null;
        const last = thread.messages[thread.messages.length - 1];
        const unread = threadUnreadCount(thread);
        return {
          key: thread.id,
          threadId: thread.id,
          groupId: null,
          person,
          title: thread.title,
          subtitle: thread.subtitle,
          navitarName:
            person?.navitarName ?? (thread.kind === 'navitar' ? thread.title : undefined),
          navitarImage: thread.navitarImage,
          element: thread.element,
          // TYPE-ONLY preview (Eddie's law): the last message's
          // text never renders here — only what kind of activity
          // it was. The words live inside the conversation.
          preview: !last
            ? 'Say hello'
            : last.from === 'you'
              ? '💬 You sent a message'
              : unread > 0
                ? '💬 New message'
                : '💬 Message',
          previewTs: last ? last.ts : null,
          sayHello: thread.messages.length === 0,
          unread,
          demo: thread.kind === 'person',
          sortTs: last ? last.ts : 0,
        };
      }),
    [threads]
  );

  const groupRows: ListRow[] = useMemo(
    () =>
      groups.map((group): ListRow => {
        const last = group.messages[group.messages.length - 1];
        const unread = groupUnreadCount(group, groupReadMap);
        return {
          key: group.id,
          threadId: null,
          groupId: group.id,
          person: null,
          title: group.name,
          subtitle: `${group.memberIds.length} ${
            group.memberIds.length === 1 ? 'member' : 'members'
          } · Group chat`,
          preview: !last
            ? '💬 Group chat — say the first word'
            : last.from === 'you'
              ? '💬 You sent a message'
              : unread > 0
                ? '💬 New group message'
                : '💬 Group message',
          previewTs: last ? last.ts : null,
          sayHello: false,
          unread,
          demo: true,
          sortTs: last ? last.ts : group.createdAt,
        };
      }),
    [groups, groupReadMap]
  );

  // Conversations sort together by last activity; say-hello friend
  // rows keep their place after them, as before.
  const rows = [
    ...[...threadRows, ...groupRows].sort((a, b) => b.sortTs - a.sortTs),
    ...friendRows,
  ];
  const selectedThread = threads.find(t => t.id === selectedId) ?? null;
  const hasAnything = rows.length > 0 || !!userNavitar;

  const openRow = (row: ListRow) => {
    if (row.groupId) {
      setSelectedId(null);
      setSelectedGroupId(row.groupId);
      setSearchParams({ group: row.groupId }, { replace: true });
      // Opening a conversation clears its unread — here, and in
      // the top-bar envelope via the store change event.
      markGroupRead(row.groupId);
      refreshGroups();
      return;
    }
    // A friend with no thread yet gets an empty one on open — the
    // player says hello first, and the person's first reply comes
    // from their scripted bank.
    const id = row.threadId ?? (row.person ? ensurePersonThread(row.person) : null);
    if (!id) return;
    setSelectedGroupId(null);
    setSelectedId(id);
    // Keep the URL in sync with the open thread (replace, so the
    // browser Back button doesn't cycle through threads): a reload
    // then lands on the thread the player is looking at, via the
    // ?thread=<id> deep-link read on mount.
    setSearchParams({ thread: id }, { replace: true });
    setMessages(getThread(id)?.messages ?? []);
    setLiveAiUnavailable(false);
    markThreadRead(id);
    refreshThreads();
  };

  const closeConversation = () => {
    setSelectedId(null);
    setSelectedGroupId(null);
    // Back to the list — clear the param so a reload shows the
    // list, not the conversation just left.
    setSearchParams({}, { replace: true });
  };

  const handleSend = () => {
    const text = input.trim();
    if (!text || typingThreadId !== null || !selectedThread) return;
    const threadId = selectedThread.id;
    const updated = appendMessage(threadId, { from: 'you', text, ts: Date.now() });
    if (!updated) return;
    // The store is the source of truth — take its messages as new state.
    setMessages(updated.messages);
    setInput('');
    setTypingThreadId(threadId);
    setLiveAiUnavailable(false);
    refreshThreads();
    timeoutRef.current = window.setTimeout(async () => {
      const reply = await getThreadReply(updated, text);
      if (!mountedRef.current) return;
      const after = appendMessage(threadId, { from: 'them', text: reply.text, ts: Date.now() });
      if (!mountedRef.current) return;
      if (after) {
        setMessages(after.messages);
        // The reply arrived in front of the player's eyes — read.
        markThreadRead(threadId);
      }
      setLiveAiUnavailable(reply.liveAiUnavailable);
      setTypingThreadId(null);
      refreshThreads();
    }, REPLY_DELAY_MS);
  };

  // Group send — the same store and the same reply bank the
  // Friends page group chat uses (utils/social.ts), so a group
  // conversation reads identically through either door.
  const handleGroupSend = () => {
    const text = groupInput.trim();
    if (!text || typingGroupId !== null || !selectedGroup || selectedGroup.left) return;
    const groupId = selectedGroup.id;
    const state = loadSocial();
    const current = state.groups.find(g => g.id === groupId);
    if (!current) return;
    saveSocial({
      ...state,
      groups: state.groups.map(g =>
        g.id === groupId
          ? { ...g, messages: [...g.messages, { from: 'you' as const, text, ts: Date.now() }] }
          : g
      ),
    });
    setGroupInput('');
    refreshGroups();
    const responder = current.memberIds
      .map(id => findPerson(id))
      .find((p): p is VenuePerson => p !== null);
    if (!responder) return;
    setTypingGroupId(groupId);
    groupTimeoutRef.current = window.setTimeout(() => {
      if (!mountedRef.current) return;
      const reply = GROUP_CHAT_REPLIES[Math.floor(Math.random() * GROUP_CHAT_REPLIES.length)];
      const latest = loadSocial();
      const g = latest.groups.find(x => x.id === groupId);
      if (!g || g.left) {
        setTypingGroupId(null);
        return;
      }
      saveSocial({
        ...latest,
        groups: latest.groups.map(x =>
          x.id === groupId
            ? {
                ...x,
                messages: [
                  ...x.messages,
                  { from: 'them' as const, author: responder.name, text: reply, ts: Date.now() },
                ],
              }
            : x
        ),
      });
      setTypingGroupId(null);
      refreshGroups();
      // Looking at the group when the reply lands = read.
      if (selectedGroupIdRef.current === groupId) markGroupRead(groupId);
    }, GROUP_REPLY_DELAY_MS);
  };

  const threadList = (
    <Paper sx={{ p: 2, height: '100%', overflowY: 'auto' }} data-testid="inbox-list">
      <Typography variant="h6" gutterBottom>
        Conversations
      </Typography>
      {rows.length === 0 ? (
        <Typography color="text.secondary">
          No messages yet — meet someone on the Realm Map (answer an icebreaker) or create a
          navitar, and their thread will show up here.
        </Typography>
      ) : (
        rows.map(row => (
          <Box
            key={row.key}
            data-testid={`inbox-row-${row.key}`}
            data-unread={row.unread}
            onClick={() => openRow(row)}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 2,
              p: 1.5,
              borderRadius: 1,
              cursor: 'pointer',
              bgcolor:
                row.threadId === selectedId || row.groupId === selectedGroupId
                  ? 'rgba(33,150,243,0.12)'
                  : 'transparent',
              '&:hover': { bgcolor: 'rgba(33,150,243,0.08)' },
            }}
          >
            {row.groupId ? (
              <GroupAvatar size={56} />
            ) : (
              <ThreadAvatar
                title={row.title}
                navitarName={row.navitarName}
                navitarImage={row.navitarImage}
                element={row.element}
                size={56}
              />
            )}
            <Box sx={{ minWidth: 0, flexGrow: 1 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography
                  variant="subtitle1"
                  noWrap
                  sx={{ fontWeight: row.unread > 0 ? 800 : 400 }}
                >
                  {row.title}
                </Typography>
                {row.demo && (
                  <Chip size="small" variant="outlined" label="DEMO" sx={{ height: 18 }} />
                )}
              </Box>
              <Typography variant="body2" color="text.secondary" noWrap>
                {row.subtitle}
              </Typography>
              <Typography
                variant="body2"
                color={row.sayHello ? 'primary' : 'text.secondary'}
                noWrap
                sx={{ fontWeight: row.unread > 0 ? 700 : 400 }}
              >
                {row.preview}
                {row.previewTs !== null && ` · ${formatTime(row.previewTs)}`}
              </Typography>
            </Box>
            {row.unread > 0 && (
              <Chip
                size="small"
                color="secondary"
                label={row.unread}
                data-testid={`inbox-unread-${row.key}`}
                sx={{ fontWeight: 800, flexShrink: 0 }}
              />
            )}
          </Box>
        ))
      )}
    </Paper>
  );

  const threadView = selectedThread ? (
    <Paper sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 0.5 }}>
        {!isDesktop && (
          <Button variant="outlined" size="small" onClick={closeConversation}>
            Back
          </Button>
        )}
        <ThreadAvatar
          title={selectedThread.title}
          navitarName={
            selectedThread.personId
              ? findPerson(selectedThread.personId)?.navitarName
              : selectedThread.kind === 'navitar'
                ? selectedThread.title
                : undefined
          }
          navitarImage={selectedThread.navitarImage}
          element={selectedThread.element}
          size={48}
        />
        <Box sx={{ minWidth: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="h6" noWrap>
              {selectedThread.title}
            </Typography>
            {selectedThread.kind === 'person' && (
              <Chip size="small" variant="outlined" label="DEMO" sx={{ height: 18 }} />
            )}
          </Box>
          <Typography variant="body2" color="text.secondary" noWrap>
            {selectedThread.subtitle}
          </Typography>
        </Box>
      </Box>
      <Typography variant="caption" color="text.secondary" sx={{ mb: 1 }}>
        {REPLY_MODE_CAPTION[replyMode]}
      </Typography>

      <Box
        ref={messagesRef}
        sx={{
          flexGrow: 1,
          overflowY: 'auto',
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          py: 1,
        }}
      >
        {messages.map((msg, idx) => (
          <Box
            key={`${msg.ts}-${idx}`}
            sx={{ display: 'flex', justifyContent: msg.from === 'you' ? 'flex-end' : 'flex-start' }}
          >
            <Box sx={{ maxWidth: '75%' }}>
              {msg.from === 'them' && (
                <Typography variant="caption" color="text.secondary">
                  {selectedThread.title}
                </Typography>
              )}
              <Box
                sx={{
                  px: 2,
                  py: 1,
                  borderRadius: 2,
                  bgcolor: msg.from === 'you' ? '#2196f3' : 'background.paper',
                  border: msg.from === 'them' ? '1px solid rgba(255,255,255,0.12)' : undefined,
                }}
              >
                <Typography variant="body1">{msg.text}</Typography>
              </Box>
              <Typography
                variant="caption"
                color="text.secondary"
                sx={{ display: 'block', textAlign: msg.from === 'you' ? 'right' : 'left' }}
              >
                {formatTime(msg.ts)}
              </Typography>
            </Box>
          </Box>
        ))}
        {typingThreadId === selectedThread.id && (
          <Box sx={{ display: 'flex', justifyContent: 'flex-start' }}>
            <Box
              sx={{
                px: 2,
                py: 1,
                borderRadius: 2,
                bgcolor: 'background.paper',
                border: '1px solid rgba(255,255,255,0.12)',
              }}
            >
              <Typography variant="body1" color="text.secondary">
                typing…
              </Typography>
            </Box>
          </Box>
        )}
      </Box>

      {liveAiUnavailable && (
        <Typography variant="caption" color="warning.main" sx={{ mb: 0.5 }}>
          Live AI is unavailable right now — answering from scripted lines.
        </Typography>
      )}
      <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
        <TextField
          fullWidth
          size="small"
          placeholder={`Message ${selectedThread.title}…`}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter') handleSend();
          }}
        />
        <Button
          variant="contained"
          onClick={handleSend}
          disabled={typingThreadId !== null || input.trim() === ''}
        >
          Send
        </Button>
      </Box>
    </Paper>
  ) : null;

  const groupView = selectedGroup ? (
    <Paper
      sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}
      data-testid="inbox-group-view"
    >
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 0.5 }}>
        {!isDesktop && (
          <Button variant="outlined" size="small" onClick={closeConversation}>
            Back
          </Button>
        )}
        <GroupAvatar size={48} />
        <Box sx={{ minWidth: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="h6" noWrap>
              {selectedGroup.name}
            </Typography>
            <Chip size="small" variant="outlined" label="DEMO" sx={{ height: 18 }} />
          </Box>
          <Typography variant="body2" color="text.secondary" noWrap>
            {selectedGroup.memberIds.length}{' '}
            {selectedGroup.memberIds.length === 1 ? 'member' : 'members'} · Group chat — the same
            conversation as on Friends &amp; Groups
          </Typography>
        </Box>
      </Box>
      <Typography variant="caption" color="text.secondary" sx={{ mb: 1 }}>
        Replies are scripted — Live AI is off.
      </Typography>

      <Box
        ref={groupMessagesRef}
        sx={{
          flexGrow: 1,
          overflowY: 'auto',
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          py: 1,
        }}
      >
        {groupMessages.length === 0 ? (
          <Typography color="text.secondary">No messages yet — say the first word.</Typography>
        ) : (
          groupMessages.map((msg, idx) => (
            <Box
              key={`${msg.ts}-${idx}`}
              sx={{
                display: 'flex',
                justifyContent: msg.from === 'you' ? 'flex-end' : 'flex-start',
              }}
            >
              <Box sx={{ maxWidth: '75%' }}>
                {msg.from !== 'you' && (
                  <Typography variant="caption" color="text.secondary">
                    {msg.from === 'navitar' ? 'Your navitar' : (msg.author ?? 'Member')}
                  </Typography>
                )}
                <Box
                  sx={{
                    px: 2,
                    py: 1,
                    borderRadius: 2,
                    bgcolor: msg.from === 'you' ? '#2196f3' : 'background.paper',
                    border: msg.from !== 'you' ? '1px solid rgba(255,255,255,0.12)' : undefined,
                  }}
                >
                  <Typography variant="body1">{msg.text}</Typography>
                </Box>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ display: 'block', textAlign: msg.from === 'you' ? 'right' : 'left' }}
                >
                  {formatTime(msg.ts)}
                </Typography>
              </Box>
            </Box>
          ))
        )}
        {typingGroupId === selectedGroup.id && (
          <Box sx={{ display: 'flex', justifyContent: 'flex-start' }}>
            <Box
              sx={{
                px: 2,
                py: 1,
                borderRadius: 2,
                bgcolor: 'background.paper',
                border: '1px solid rgba(255,255,255,0.12)',
              }}
            >
              <Typography variant="body1" color="text.secondary">
                typing…
              </Typography>
            </Box>
          </Box>
        )}
      </Box>

      <Box sx={{ display: 'flex', gap: 1, mt: 1 }}>
        <TextField
          fullWidth
          size="small"
          placeholder={`Message ${selectedGroup.name}…`}
          value={groupInput}
          onChange={e => setGroupInput(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter') handleGroupSend();
          }}
        />
        <Button
          variant="contained"
          onClick={handleGroupSend}
          disabled={typingGroupId !== null || groupInput.trim() === ''}
        >
          Send
        </Button>
      </Box>
    </Paper>
  ) : null;

  const conversationView = threadView ?? groupView ?? (
    <Paper sx={{ p: 3, height: '100%' }}>
      <Typography color="text.secondary">
        Pick a conversation to start chatting — or meet someone new on the Realm Map.
      </Typography>
    </Paper>
  );

  const anySelected = selectedId !== null || selectedGroupId !== null;

  return (
    <Box sx={{ py: 4 }} data-testid="inbox-page">
      <Typography variant="h4" gutterBottom>
        Inbox
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Every conversation in one place. Notifications only ever say the type — the words themselves
        live here, inside the conversation. Demo conversations with GLACER’s demo people, on this
        device only.
      </Typography>
      {!hasAnything ? (
        <Paper sx={{ p: 3 }}>
          <Typography color="text.secondary">
            No messages yet — meet someone on the Realm Map (answer an icebreaker) or create a
            navitar, and their thread will show up here.
          </Typography>
        </Paper>
      ) : isDesktop ? (
        <Box sx={{ display: 'flex', gap: 2, height: '70vh' }}>
          <Box sx={{ width: '33%', flexShrink: 0 }}>{threadList}</Box>
          <Box sx={{ flexGrow: 1, minWidth: 0 }}>{conversationView}</Box>
        </Box>
      ) : (
        <Box sx={{ height: '70vh' }}>{anySelected ? conversationView : threadList}</Box>
      )}
    </Box>
  );
};

export default Messages;
