import React, { useEffect, useState } from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  Chip,
  IconButton,
  Menu,
  MenuItem,
  Switch,
  Badge,
} from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import NotificationsIcon from '@mui/icons-material/Notifications';
import MailIcon from '@mui/icons-material/Mail';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { DISPLAY_NAME_KEY } from '../utils/accountMerge';
import { useViewMode } from '../contexts/ViewModeContext';
import { useNotifications } from '../contexts/NotificationsContext';
import {
  THREADS_CHANGED_EVENT,
  loadThreads,
  migrateThreadReadState,
  totalThreadUnread,
} from '../utils/threads';
import {
  SOCIAL_CHANGED_EVENT,
  groupUnreadCount,
  loadGroupLastRead,
  loadSocial,
  migrateGroupReadState,
} from '../utils/social';
import SoundToggle from './SoundToggle';

const LINKS = [
  { to: '/battle', label: 'Battle' },
  { to: '/networking', label: 'Networking' },
  { to: '/friends', label: 'Friends' },
  { to: '/collection', label: 'Navidex' },
  { to: '/map', label: 'World Map' },
  { to: '/forums', label: 'Forums' },
  { to: '/messages', label: 'Inbox' },
  { to: '/notifications', label: 'Notifications' },
  { to: '/pirates', label: 'Pirates' },
  { to: '/stroll', label: 'Stroll' },
  { to: '/ar', label: 'AR View' },
  { to: '/venues', label: 'For Venues' },
  { to: '/features', label: 'All Features' },
  { to: '/wallet', label: 'Wallet' },
  { to: '/profile', label: 'Profile' },
];

// The Modern View's 3D Models toggle (Eddie, 2026-11-16): one
// switch flips every fighter surface between the 2D art and the
// real 3D GLB models — Navidex grid ⇄ stage, and the same value is
// read by Home and Battle. Kept compact so it fits the phone header
// next to the wordmark (the prototype's clipped-toggle bug does not
// ship twice).
const ViewModeToggle: React.FC = () => {
  const { viewMode, toggleViewMode } = useViewMode();
  const is3d = viewMode === '3d';
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mr: { xs: 0, sm: 1 } }}>
      {/* The mode caption hides on phone widths (Round 17 fit
          trim): the top bar gained the notifications bell, and the
          cluster's min-content overflowed a 390px phone, widening
          every page's layout. The switch (with its aria-label)
          stays; the caption returns at sm and up. */}
      <Typography
        variant="caption"
        sx={{ fontWeight: 700, letterSpacing: '0.04em', display: { xs: 'none', sm: 'block' } }}
      >
        {is3d ? '3D' : 'Card'}
      </Typography>
      <Switch
        size="small"
        checked={is3d}
        onChange={toggleViewMode}
        inputProps={{ 'aria-label': 'Toggle between Card and 3D view' }}
        data-testid="nav-3d-toggle"
      />
      <Typography
        variant="caption"
        sx={{ display: { xs: 'none', sm: 'block' }, color: 'text.secondary' }}
      >
        Models
      </Typography>
    </Box>
  );
};

// The notifications bell (Round 17, Eddie 2026-11-17): the door
// to the notifications home (/notifications) — "a place where your
// notifications are showed." The badge is the store's unread
// count; it hides itself at zero. Present in both the desktop row
// and the phone cluster, like the sound toggle.
const NotificationsBell: React.FC = () => {
  const { unreadCount } = useNotifications();
  return (
    <IconButton
      component={RouterLink}
      to="/notifications"
      color="inherit"
      aria-label={unreadCount > 0 ? `Notifications, ${unreadCount} unread` : 'Notifications'}
      data-testid="nav-notifications-bell"
      sx={{ p: { xs: 0.375, sm: 1 } }}
    >
      <Badge badgeContent={unreadCount} color="secondary" data-testid="nav-notifications-badge">
        <NotificationsIcon />
      </Badge>
    </IconButton>
  );
};

// The Inbox envelope (Round 22, Eddie 2026-11-18): the door to
// the messages Inbox (/messages), badged with the TOTAL unread
// across every conversation — 1:1 threads, the navitar thread
// and group chats. The count is computed from the stores (the
// one source of truth) and refreshed on every store change
// event, route change and window focus, so it can never drift
// from what the Inbox itself shows. The badge carries a count
// only — never message text (Eddie's type-only law).
function totalInboxUnread(): number {
  const threads = totalThreadUnread(loadThreads());
  const readMap = loadGroupLastRead();
  const groups = loadSocial()
    .groups.filter(g => !g.left)
    .reduce((sum, g) => sum + groupUnreadCount(g, readMap), 0);
  return threads + groups;
}

const MessagesEnvelope: React.FC = () => {
  const [unread, setUnread] = useState<number>(() => totalInboxUnread());
  const location = useLocation();

  useEffect(() => {
    // First sight of the read-state era: stamp legacy history as
    // read so nobody is badged for old conversations.
    migrateThreadReadState();
    migrateGroupReadState(loadSocial().groups);
    setUnread(totalInboxUnread());
  }, []);

  useEffect(() => {
    const refresh = () => setUnread(totalInboxUnread());
    refresh();
    window.addEventListener(THREADS_CHANGED_EVENT, refresh);
    window.addEventListener(SOCIAL_CHANGED_EVENT, refresh);
    window.addEventListener('storage', refresh);
    window.addEventListener('focus', refresh);
    return () => {
      window.removeEventListener(THREADS_CHANGED_EVENT, refresh);
      window.removeEventListener(SOCIAL_CHANGED_EVENT, refresh);
      window.removeEventListener('storage', refresh);
      window.removeEventListener('focus', refresh);
    };
  }, [location.pathname, location.search]);

  return (
    <IconButton
      component={RouterLink}
      to="/messages"
      color="inherit"
      aria-label={unread > 0 ? `Inbox, ${unread} unread messages` : 'Inbox'}
      data-testid="nav-messages-envelope"
      sx={{ p: { xs: 0.375, sm: 1 } }}
    >
      <Badge badgeContent={unread} color="secondary" data-testid="nav-messages-badge">
        <MailIcon />
      </Badge>
    </IconButton>
  );
};

// The account cluster (Step 4, 2026-11-14): sign-in used to live
// only inside the Profile page, so most players never found it.
// The nav now carries it everywhere: signed out → Log in / Sign up
// (both land on the Profile account card); signed in → a chip with
// the player's name and a Log out button. Signing in is never
// required to play — this is a door, not a wall.
const NavAuthCluster: React.FC<{ onNavigate?: () => void }> = ({ onNavigate }) => {
  const { user, loading, signOut } = useAuth();
  // The chip name: the merged display name (accountMerge keeps the
  // local key in sync with the account), else the email. Re-read on
  // auth changes and whenever the key changes in another surface.
  const [name, setName] = useState<string | null>(null);
  useEffect(() => {
    const read = () => {
      try {
        setName(localStorage.getItem(DISPLAY_NAME_KEY));
      } catch {
        setName(null);
      }
    };
    read();
    window.addEventListener('storage', read);
    return () => window.removeEventListener('storage', read);
  }, [user]);

  if (loading) return null;
  if (!user) {
    return (
      <Box sx={{ display: 'flex', gap: { xs: 0.25, sm: 1 }, alignItems: 'center' }}>
        <Button
          component={RouterLink}
          to="/profile#account"
          color="inherit"
          size="small"
          data-testid="nav-login"
          onClick={onNavigate}
          sx={{ px: { xs: 0.5, sm: 1 } }}
        >
          Log in
        </Button>
        <Button
          component={RouterLink}
          to="/profile#account"
          variant="outlined"
          color="inherit"
          size="small"
          data-testid="nav-signup"
          onClick={onNavigate}
          sx={{ px: { xs: 0.5, sm: 1 } }}
        >
          Sign up
        </Button>
      </Box>
    );
  }
  return (
    <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
      <Chip
        label={name?.trim() ? name : user.email}
        size="small"
        color="primary"
        data-testid="nav-user-chip"
        component={RouterLink}
        to="/profile"
        clickable
        sx={{ maxWidth: 180 }}
      />
      <Button
        color="inherit"
        size="small"
        data-testid="nav-logout"
        onClick={() => {
          onNavigate?.();
          void signOut();
        }}
      >
        Log out
      </Button>
    </Box>
  );
};

const Navbar: React.FC = () => {
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const menuOpen = Boolean(anchorEl);

  return (
    <AppBar position="static" color="transparent" elevation={1}>
      {/* Phone widths get tighter toolbar padding (Round 17 fit
          trim): with the notifications bell added, the bar's
          min-content ran ~15px past a 390px phone and widened
          every page's layout viewport. Desktop padding (24px)
          is unchanged. Round 22 fit trim: the Inbox envelope
          added ~36px more, so the phone cluster's gaps, the
          bell/envelope padding and the auth buttons' padding
          tightened on xs only — desktop is untouched, again. */}
      <Toolbar sx={{ px: { xs: 1, sm: 3 } }}>
        <Typography
          variant="h6"
          component={RouterLink}
          to="/"
          sx={{
            flexGrow: 1,
            textDecoration: 'none',
            color: 'inherit',
            fontWeight: 'bold',
            // A touch smaller on phones (Round 17 fit trim) — the
            // last few px the bell needed. Full size from sm up.
            fontSize: { xs: '1.08rem', sm: '1.25rem' },
          }}
        >
          GLACER
        </Typography>

        {/* Desktop: the full row. On phones the row is ~850px wide and
            forces horizontal scrolling, hiding the later links entirely —
            so below the md breakpoint it collapses into a menu. */}
        <Box sx={{ display: { xs: 'none', md: 'flex' }, gap: 2, alignItems: 'center' }}>
          {/* Battle used to be disabled until a navitar was selected in a
              different navitar model than the one the Battle page actually
              uses, so the link could never enable. The Battle page renders
              fine and now offers to create a Navitar when none exists. */}
          {LINKS.map(link => (
            <Button key={link.to} component={RouterLink} to={link.to} color="inherit">
              {link.label}
            </Button>
          ))}
          <ViewModeToggle />
          <SoundToggle />
          <MessagesEnvelope />
          <NotificationsBell />
          <NavAuthCluster />
        </Box>

        <Box
          sx={{
            display: { xs: 'flex', md: 'none' },
            alignItems: 'center',
            gap: { xs: 0, sm: 0.5 },
          }}
        >
          <ViewModeToggle />
          <SoundToggle />
          <MessagesEnvelope />
          <NotificationsBell />
          <NavAuthCluster />
          <IconButton
            color="inherit"
            aria-label="Open menu"
            aria-controls={menuOpen ? 'nav-menu' : undefined}
            aria-haspopup="true"
            aria-expanded={menuOpen ? 'true' : undefined}
            onClick={e => setAnchorEl(e.currentTarget)}
            sx={{ p: { xs: 0.75, sm: 1 } }}
          >
            <MenuIcon />
          </IconButton>
          <Menu id="nav-menu" anchorEl={anchorEl} open={menuOpen} onClose={() => setAnchorEl(null)}>
            {LINKS.map(link => (
              <MenuItem
                key={link.to}
                component={RouterLink}
                to={link.to}
                onClick={() => setAnchorEl(null)}
              >
                {link.label}
              </MenuItem>
            ))}
          </Menu>
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
