const GEAR = ['Crystal Collar', 'Frost Saddle', 'Ember Harness', 'Star Charm', 'Tide Ribbon'];

const NavidexStage: React.FC = () => {
  const ownerMode = useOwnerMode();
  // Chosen state reads the SAME source of truth the Choose button
  // writes: FightClub's userNavitar (derived from
  // glacer-active-navitar-id). No parallel selection state here.
  const { navitars: ownedNavitars, userNavitar } = useNavitarFightClub();
  // FULL STAGE ROSTER (Round 16, Eddie 2026-11-17): every fighter
  // with a verified 3D model is Stage-reachable — for EVERY
  // viewer, owner or not. The Stage used to gate its extras
  // behind Owner Mode (a non-owner swiped 11 fighters; the owner
  // 21), and 8 modeled fighters were never staged at all:
  // Sundermaw, Cindermother, Heartroot, Erebane and Solara (their
  // models sat in BASE_MODELS with no BASE_STAGE entry) and
  // Ignivar the Gateforge, Hiveheart and Aleator (collection
  // designs whose models only the owner's battle records used).
  // Eddie's law: the Navidex shows the full roster to browse;
  // SELECTION is what ownership gates (the lock treatment below),
  // not visibility. Ordering: the 21 fighters already staged keep
  // their exact relative order (Prime Zero, the four staged
  // Primes, the five Realm candidates, the base eleven); the 8
  // newly staged append after them — the five Primes in
  // PRIME_DESIGNS order, then the three collection fighters in
  // COLLECTION_DESIGNS order. Owner Mode now changes only Prime
  // Zero's tag (and, through FightClub's merged collection, the
  // fact that everything is the owner's to choose).
  const roster = useMemo<StageFighter[]>(() => {
    const models = { ...BASE_MODELS, ...OWNER_MODELS };
    const fromDesign = (
      d: { name: string; element: string },
      level: number,
      tag?: string
    ): StageFighter | null => {
      const m = models[d.name];
      return m
        ? {
            name: d.name,
            element: d.element,
            level,
            modelUrl: m.modelUrl,
            modelZoom: m.modelZoom,
            tag,
          }
        : null;
    };
    const staged: (StageFighter | null)[] = [
      {
        name: PRIME_ZERO_DESIGN.name,
        element: PRIME_ZERO_DESIGN.element,
        level: 30,
        modelUrl: models['Prime Zero'].modelUrl,
        tag: ownerMode ? 'PRIME ZERO — YOURS ALONE' : 'PRIME ZERO — SOULBOUND 1/1',
      },
      ...PRIME_DESIGNS.filter(d => OWNER_MODELS[d.name]).map(d => fromDesign(d, 25, 'PRIME')),
      ...REALM_CANDIDATE_DESIGNS.filter(d => OWNER_MODELS[d.name]).map(d =>
        fromDesign(d, 20, 'REALM BATCH CANDIDATE')
      ),
      ...BASE_STAGE.map(f => ({ ...f, ...(BASE_MODELS[f.name] ?? {}) })),
      // The 8 newly staged (Round 16): the five unstaged Primes,
      // then the three modeled collection fighters.
      ...PRIME_DESIGNS.filter(d => !OWNER_MODELS[d.name]).map(d => fromDesign(d, 25, 'PRIME')),
      ...COLLECTION_DESIGNS.filter(
        d =>
          OWNER_MODELS[d.name] &&
          d.name !== PRIME_ZERO_DESIGN.name &&
          !PRIME_DESIGNS.some(p => p.name === d.name) &&
          !REALM_CANDIDATE_DESIGNS.some(c => c.name === d.name)
      ).map(d => fromDesign(d, 20)),
    ];
    const seen = new Set<string>();
    return staged.filter((f): f is StageFighter => {
      if (!f || !f.modelUrl || seen.has(f.name)) return false;
      seen.add(f.name);
      return true;
    });
  }, [ownerMode]);

  const [index, setIndex] = useState(0);
  const fighter = roster[Math.min(index, roster.length - 1)];
  const fighterIsChosen =
    !!userNavitar && ownedNavitars.some(n => n.id === userNavitar.id && n.name === fighter.name);
  // Owned-only selection (Round 16): a staged fighter is LOCKED
  // for this viewer when no collection record carries its name.
  // In Owner Mode FightClub's collection includes every design,
  // so nothing is locked for the owner — exactly as before. The
  // Stage still STANDS the fighter for everyone (browsing is the
  // Navidex's job); only the choose controls give way to the lock.
  const fighterLocked = !ownedNavitars.some(n => n.name === fighter.name);
  const [care, setCare] = useState<StageCare>(() => getCare(fighter.name));
  // Name of the fighter whose 3D model failed to load/render (e.g.
  // no WebGL in this browser) — the stage shows its portrait instead.
  // Round 6: a failure is NOT sticky for the session — goTo clears
  // it, so re-staging the fighter retries the model (a transient
  // network/context failure used to mean "picture forever").
  const [modelFailedFor, setModelFailedFor] = useState<string | null>(null);
  // Name of the fighter whose GLB has finished loading. Until it
  // lands, the stage shows the portrait under a loading veil (the
  // ModelViewer pattern) — the swap to 3D happens once, on load,
  // never flapping between the two.
  const [modelLoadedFor, setModelLoadedFor] = useState<string | null>(null);
  const [panel, setPanel] = useState<'none' | 'modify' | 'bag'>('none');
  // Lore panel (Round 9, Eddie 2026-11-16: "when the character['s
  // in] 3-D mode can we display the lore to the side"): on wide
  // screens the lore sits in a side panel next to the model; on
  // phone it hides behind this toggle (collapsed by default — the
  // Round 6 fit budget leaves no room for an always-on block).
  const [loreOpen, setLoreOpen] = useState(false);
  // Motion state (Eddie, 2026-11-16 — motion signatures round):
  // `action` is the fighter's SIGNATURE ACTION (ambient, Train, or
  // the Choose victory flourish); `react` is a short interaction
  // reaction (feed hop / modify twirl / item glow pulse). At most
  // one of them drives the model wrapper at a time — see
  // motionClass below. Both are pure presentation: the care
  // effects (bond/XP/items) land immediately and never wait on
  // these timers.
  const [action, setAction] = useState<{
    key: number;
    kind: SignatureActionKind;
    source: 'ambient' | 'train' | 'choose';
  } | null>(null);
  const [react, setReact] = useState<'feed' | 'spin' | 'pulse' | null>(null);
  const [burst, setBurst] = useState(false);
  const [note, setNote] = useState<string | null>(null);
  const touchX = useRef<number | null>(null);
  // ---- Stage swipe gesture (Round 7 restore) -------------------
  // Round 6 removed ModelCanvas's OrbitControls — deliberately
  // (Eddie's no-grab-orbit law) — but OrbitControls had been
  // quietly carrying the Stage swipe: it set touch-action:none on
  // the canvas and preventDefaulted pointerdown, so the browser
  // never claimed a drag on the model as a page scroll and the
  // Stage's touchend always fired. Without it, iOS Safari (which
  // ignores touch-action: pan-y) scroll-claims horizontal drags
  // and fires touchcancel instead of touchend — the swipe died.
  // The restore is a direction-locked gesture layer: pointer
  // events track the drag, and a native non-passive touchmove
  // guard preventDefaults ONLY once a drag is clearly horizontal,
  // so the browser can never claim a horizontal swipe — while a
  // vertical drag is released to page scroll untouched. Nothing
  // here rotates the model or the camera; the model's own ±yaw
  // sway is untouched.
  // Round 9 (Eddie, 2026-11-16): the Round 7 layer lived on the
  // MODEL BLOCK only — but Eddie swipes the stage as a whole, and
  // a swipe starting on the header or the floor band still died
  // (no guard there, so Safari scroll-claimed it into a
  // touchcancel). The surface is now the WHOLE .glacer-stage card:
  // handlers + guard live on the card itself. Two boundaries:
  // gestures starting inside an open Modify/Bag panel are exempt
  // (data-noswipe — no flipping fighters mid-interaction), and a
  // click that belongs to a just-finished swipe is swallowed in
  // capture phase (lastSwipeNavAt) so a drag ending on a button
  // can't ALSO fire that button — taps (sub-threshold movement)
  // are never touched and click normally.
  const lastSwipeNavAt = useRef(0);
  const swipeGesture = useRef<{
    x: number;
    y: number;
    lock: 'h' | 'v' | null;
    done: boolean;
  } | null>(null);
  // Pointer and touch completions both arrive for one physical
  // gesture (pointerup first, then touchend): whichever gets
  // there first consumes it, the other stands down.
  const gestureConsumed = useRef(false);
  // Gestures that start inside an open action panel (Modify/Bag)
  // never become swipes — the panel is an interaction surface, not
  // stage floor. Panels mark themselves with data-noswipe.
  const swipeStartOk = (target: EventTarget | null): boolean => {
    const el = target as HTMLElement | null;
    return !el || typeof el.closest !== 'function' || !el.closest('[data-noswipe]');
  };
  const beginSwipe = (x: number, y: number) => {
    swipeGesture.current = { x, y, lock: null, done: false };
    gestureConsumed.current = false;
  };
  // Track the drag: returns the horizontal delta once the gesture
  // is locked horizontal, null while undecided or vertical.
  const trackSwipe = (x: number, y: number): number | null => {
    const g = swipeGesture.current;
    if (!g) return null;
    const dx = x - g.x;
    const dy = y - g.y;
    if (!g.lock) {
      if (Math.abs(dx) < 10 && Math.abs(dy) < 10) return null;
      g.lock = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v';
    }
    return g.lock === 'h' ? dx : null;
  };
  const endSwipe = (x: number) => {
    const g = swipeGesture.current;
    swipeGesture.current = null;
    if (!g || g.done || gestureConsumed.current) return;
    gestureConsumed.current = true;
    const dx = x - g.x;
    if (g.lock === 'h' && Math.abs(dx) > 48) {
      g.done = true;
      // Stamp the navigation: the capture-phase click guard (in
      // the effect below) eats the click this same gesture would
      // otherwise land on a button it started or ended on.
      lastSwipeNavAt.current = Date.now();
      goTo(index + (dx < 0 ? 1 : -1));
    }
  };
  // The iOS guard: a NON-PASSIVE touchmove listener on the whole
  // stage card (React attaches touch listeners passively, so this
  // must be native). Once a drag reads horizontal-dominant it
  // preventDefaults — Safari then keeps the gesture with the app
  // and touchend/pointerup arrive, wherever on the card the drag
  // started (Round 9: header and floor band included, not just
  // the model). Vertical drags are never prevented, so page
  // scroll starting on the card still works. The same effect owns
  // the capture-phase click guard: on the pointer path a
  // horizontal drag that starts and ends on the same button would
  // still deliver that button's click AFTER the swipe navigated —
  // a click within 350ms of a swipe navigation belongs to the
  // swipe and is eaten here, before React ever sees it. (On touch,
  // the touchmove preventDefault already suppresses that click;
  // this covers mouse/pen.) stageRef is declared below with the
  // ambient wiring — the effect runs after mount, when the ref is
  // live (the same pattern as endSwipe calling goTo).
  useEffect(() => {
    const el = stageRef.current;
    if (!el) return;
    const onMove = (e: TouchEvent) => {
      const g = swipeGesture.current;
      if (!g || g.done) return;
      const t = e.touches[0];
      if (!t) return;
      if (trackSwipe(t.clientX, t.clientY) !== null && e.cancelable) {
        e.preventDefault();
      }
    };
    const onClickCapture = (e: MouseEvent) => {
      if (Date.now() - lastSwipeNavAt.current < 350) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    el.addEventListener('touchmove', onMove, { passive: false });
    el.addEventListener('click', onClickCapture, true);
    return () => {
      el.removeEventListener('touchmove', onMove);
      el.removeEventListener('click', onClickCapture, true);
    };
  }, []);
  const actionTimer = useRef(0);
  const reactTimer = useRef(0);
  const reducedMotion = usePrefersReducedMotion();
  // This fighter's motion signature: its own idle style + speed +
  // phase, and its element's signature action. Deterministic —
  // the same fighter always moves the same way.
  const sig = useMemo(
    () => motionSignatureFor(fighter.name, fighter.element),
    [fighter.name, fighter.element]
  );

  // ---- Ambient life + motion signatures (Eddie, 2026-11-16) ---
  // The staged navitar feels alive at rest, in ITS OWN way
  // (utils/motionSignature.ts): an idle style that's per-navitar
  // (bob / sway / rock / slow-spin / pulse / hover / prowl — one
  // motion system on the model wrapper, replacing the generic
  // sway every fighter used to share), its element dripping
  // behind it (ElementalAmbience, attackFx palette), small ambient
  // energy shots every ~6–12s, and — the headline — its SIGNATURE
  // ACTION every ~14–25s: a fire dragon rears and blows fire, an
  // ice dragon dips and breathes frost, a shade sinks into its
  // wisps. Doing something FOR it gets an answer too: Feed hops,
  // Modify twirls, a bag item lands as a glow pulse, Train runs
  // the full signature action, and Choose answers with a victory
  // flourish + gold ring flash.
  //
  // HONESTY: the GLBs are single merged meshes (verified across
  // every model — one node, one mesh, no wing/part nodes, no
  // rig), so all of this is stage presentation — transforms on
  // the model wrapper + attackFx particles — never claimed as
  // rigged animation, and the footer copy says so.
  //
  // The whole ambient layer pauses when the stage is off-screen,
  // the tab is hidden, or the user prefers reduced motion
  // (useAmbientActive); under reduced motion the manual reactions
  // also stand down to a static state (triggerAction/triggerReact
  // check usePrefersReducedMotion). There is no separate Smooth
  // toggle in the real app (that was the prototype), so the OS
  // setting is the off switch — nothing conflicting was invented.
  const stageRef = useRef<HTMLDivElement>(null);
  const ambientActive = useAmbientActive(stageRef);
  const [shot, setShot] = useState<{ key: number; kind: AnimClass } | null>(null);

  // Fire the fighter's signature action (or stand down under
  // reduced motion). Presentation only — callers apply their real
  // effects (training record, care, choice) themselves, first.
  const triggerAction = useCallback(
    (source: 'ambient' | 'train' | 'choose') => {
      if (reducedMotion) return;
      window.clearTimeout(actionTimer.current);
      setAction({ key: Date.now(), kind: sig.action, source });
      // Sound: breath-family actions ride the beam voice; the
      // crackle rides the burst; everything else resolves through
      // the same attackFx classification battle uses (power =
      // beam for beam-apt elements, heavy burst otherwise). A
      // player-triggered action also gets the fighter's cry; the
      // ambient one stays quieter (FX only).
      if (sig.action === 'breath' || sig.action === 'frostbreath' || sig.action === 'jet') {
        playFxSound('beam', fighter.element, sig.action === 'breath');
      } else if (sig.action === 'crackle') {
        playFxSound('burst', fighter.element);
      } else {
        playFxSound(
          animClassForMove({ moveKind: 'power', name: fighter.name, element: fighter.element }),
          fighter.element
        );
      }
      if (source !== 'ambient') playNavitarCry(fighter.element);
      actionTimer.current = window.setTimeout(() => setAction(null), 1500);
    },
    [reducedMotion, sig.action, fighter.element, fighter.name]
  );

  // A short interaction reaction (feed / modify / bag item).
  const triggerReact = useCallback(
    (kind: 'feed' | 'spin' | 'pulse', withBurst: boolean) => {
      window.clearTimeout(reactTimer.current);
      if (reducedMotion) {
        setReact(null);
        setBurst(false);
        return;
      }
      setReact(kind);
      if (withBurst) setBurst(true);
      reactTimer.current = window.setTimeout(() => {
        setReact(null);
        setBurst(false);
      }, 950);
    },
    [reducedMotion]
  );

  // Unmount: no timers outlive the stage.
  useEffect(
    () => () => {
      window.clearTimeout(actionTimer.current);
      window.clearTimeout(reactTimer.current);
    },
    []
  );

  useEffect(() => {
    if (!ambientActive || action || react) return;
    let alive = true;
    let shotTimer = 0;
    let clearTimer = 0;
    const schedule = () => {
      shotTimer = window.setTimeout(
        () => {
          if (!alive) return;
          const kind = animClassForMove({
            moveKind: 'skill',
            name: fighter.name,
            element: fighter.element,
            signature: true,
          });
          setShot({ key: Date.now(), kind });
          // The ambient shot has a voice too — the same synth FX
          // family as battle, at ambient scale (utils/sound.ts).
          playFxSound(kind, fighter.element);
          clearTimer = window.setTimeout(() => {
            if (alive) setShot(null);
          }, 780);
          schedule();
        },
        6000 + Math.random() * 6000
      );
    };
    schedule();
    return () => {
      alive = false;
      window.clearTimeout(shotTimer);
      window.clearTimeout(clearTimer);
    };
  }, [ambientActive, action, react, fighter.name, fighter.element]);

  // The signature action, ambient: every ~14–25s, randomized,
  // only while the stage is live (ambientActive already folds in
  // on-screen + tab-visible + not-reduced-motion) and nothing
  // else is performing. One action at a time, by construction.
  useEffect(() => {
    if (!ambientActive || action || react) return;
    let alive = true;
    const t = window.setTimeout(
      () => {
        if (alive) triggerAction('ambient');
      },
      14000 + Math.random() * 11000
    );
    return () => {
      alive = false;
      window.clearTimeout(t);
    };
  }, [ambientActive, action, react, triggerAction]);

  const goTo = (next: number) => {
    const wrapped = (next + roster.length) % roster.length;
    // A swipe cancels any performance in flight — the old fighter
    // never finishes its flourish over the new one's entrance.
    window.clearTimeout(actionTimer.current);
    window.clearTimeout(reactTimer.current);
    setAction(null);
    setReact(null);
    setBurst(false);
    setIndex(wrapped);
    setCare(getCare(roster[wrapped].name));
    setPanel('none');
    setNote(null);
    setShot(null);
    // Re-staging retries the 3D model: clear any recorded failure
    // and any stale loaded mark, so the incoming fighter gets a
    // fresh load (veil → 3D) instead of inheriting a portrait.
    setModelFailedFor(null);
    setModelLoadedFor(null);
    // Selecting a navitar on the Stage: it answers with its
    // element-flavored cry (synth, utils/sound.ts).
    playNavitarCry(roster[wrapped].element);
  };

  const left = trainingsLeftToday(fighter.name, fighter.level);

  const onTrain = () => {
    if (left <= 0) {
      setNote(
        `${fighter.name} has trained enough today — the cooldown resets tomorrow. Rest is part of training.`
      );
      return;
    }
    recordTraining(fighter.name);
    const next = updateCare(fighter.name, {
      xp: care.xp + TRAINING_XP,
      bond: care.bond + TRAIN_BOND,
    });
    setCare(next);
    // Training IS the signature action now (Eddie, 2026-11-16):
    // the fighter shows its full flourish — a fire dragon blows
    // fire — while the XP/bond land immediately, as always.
    triggerAction('train');
    setNote(
      `${fighter.name} trained! +${TRAINING_XP} XP · +${TRAIN_BOND} bond · ${
        left - 1 > 0 ? `${left - 1} session left today` : 'daily training complete'
      }`
    );
  };

  const onFeed = () => {
    const next = updateCare(fighter.name, { bond: care.bond + FEED_BOND });
    setCare(next);
    // The happy answer: a hop in its own style's family + an
    // element sparkle + its cry pitched as pure contentment
    // (the same synth voice — joy is in the bounce).
    triggerReact('feed', true);
    playNavitarCry(fighter.element);
    setNote(`${fighter.name} loved that. +${FEED_BOND} bond.`);
  };

  const onModifyToggle = () => {
    const opening = panel !== 'modify';
    setPanel(opening ? 'modify' : 'none');
    // Opening Modify: the fighter twirls to show off the look.
    if (opening) triggerReact('spin', true);
  };

  const toggleGear = (item: string) => {
    const gear = care.gear.includes(item)
      ? care.gear.filter(g => g !== item)
      : [...care.gear, item];
    const next = updateCare(fighter.name, { gear });
    setCare(next);
    // A look change lands as a glow pulse.
    triggerReact('pulse', false);
  };

  // ONE motion system on the model wrapper (Eddie, 2026-11-16):
  // a signature action outranks a reaction, which outranks the
  // idle signature; the ambient lunge-shot borrows the wrapper
  // only when nothing else is performing. The chosen-flash rides
  // alongside a Choose-triggered action.
  // SPIN fighters (Round 6, Eddie's presentation law): the old
  // DOM sig-spin ran rotateY(360°) on the canvas wrapper — the
  // model visibly flipped flat like a card. A "spin" fighter now
  // turns IN-SCENE instead: ModelCanvas gets the wide ±30° yaw
  // sway (left ↔ right, always upright, never a full turn), and
  // the wrapper borrows the gentle sway idle so the DOM layer
  // never rotateY's at all.
  const motionClass = action
    ? `sigact ${actionMotionClass(action.kind, sig.style)}`
    : react
      ? `react-${react}`
      : ambientActive
        ? `sig-idle sig-${sig.style === 'spin' ? 'sway' : sig.style}`
        : '';
  const fx = fxColors(fighter.element);
  // Real lore only (utils/navitarArt NAVITAR_LORE — the same text
  // the collection cards carry on their Lore tab): the 9 heroes +
  // Ashwing + Griffin have entries. Fighters without an entry —
  // the Primes, Prime Zero, the realm candidates, the extra
  // modeled roster — show NO lore panel; nothing is invented for
  // them. (NAVITAR_LORE's 'navitarZero' entry belongs to the
  // arena's announcer/boss record, not to Prime Zero, so Prime
  // Zero correctly gets no panel rather than borrowed lore.)
  const lore = getNavitarLore(fighter.name);
  // Signature-FX spray: six orbs on fixed fanned vectors (the
  // beam/cone/ring carries the shape; the orbs carry the spray).
  // 6 orbs + 1 shape + 1 wash stays far under the ≤40 law.
  const SIG_ORBS = [
    { dx: '118px', dy: '-32px', s: 13, d: 0 },
    { dx: '152px', dy: '8px', s: 10, d: 0.06 },
    { dx: '92px', dy: '-58px', s: 11, d: 0.03 },
    { dx: '164px', dy: '-46px', s: 9, d: 0.09 },
    { dx: '78px', dy: '24px', s: 12, d: 0.05 },
    { dx: '132px', dy: '34px', s: 8, d: 0.12 },
  ];

  return (
    <Box sx={{ mb: 5 }}>
      <Box
        className="glacer-stage"
        ref={stageRef}
        onTouchStart={e => {
          // Panel-exempt (Round 9): a touch that starts inside an
          // open Modify/Bag panel never becomes a swipe.
          if (!swipeStartOk(e.target)) {
            touchX.current = null;
            return;
          }
          touchX.current = e.touches[0].clientX;
          beginSwipe(e.touches[0].clientX, e.touches[0].clientY);
        }}
        onPointerDown={e => {
          if (swipeStartOk(e.target)) beginSwipe(e.clientX, e.clientY);
        }}
        onPointerMove={e => {
          trackSwipe(e.clientX, e.clientY);
        }}
        onPointerUp={e => endSwipe(e.clientX)}
        onPointerCancel={() => {
          swipeGesture.current = null;
        }}
        onTouchEnd={e => {
          // Pointer and touch completion both funnel into
          // endSwipe, which navigates at most once per gesture.
          if (swipeGesture.current) {
            endSwipe(e.changedTouches[0].clientX);
            touchX.current = null;
            return;
          }
          // The pointer path already consumed this gesture.
          if (gestureConsumed.current) {
            touchX.current = null;
            return;
          }
          if (touchX.current === null) return;
          const dx = e.changedTouches[0].clientX - touchX.current;
          touchX.current = null;
          if (Math.abs(dx) > 48) goTo(index + (dx < 0 ? 1 : -1));
        }}
        onTouchCancel={() => {
          // A scroll-claimed gesture ends here, not in a swipe.
          touchX.current = null;
          swipeGesture.current = null;
        }}
      >
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            p: { xs: 1.25, sm: 2 },
          }}
        >
          <IconButton
            aria-label="Previous navitar"
            onClick={() => goTo(index - 1)}
            sx={{ color: '#eaf6fa' }}
          >
            <ChevronLeftIcon fontSize="large" />
          </IconButton>
          <Box sx={{ textAlign: 'center' }}>
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 0.75,
              }}
            >
              <Typography variant="h5" sx={{ color: '#eaf6fa', fontWeight: 700 }}>
                {elementEmoji(fighter.element)} {fighter.name}
              </Typography>
              {/* The ✓ CHECK on the staged fighter's card (Eddie,
                  2026-11-16 ~13:46 PT): "that's where you pick
                  your avatar right there." Same control as the
                  grid cards, same one write path — tapping it
                  chooses this fighter and fires the victory
                  flourish, exactly like the big Choose button
                  below the stage. Round 16: for a fighter this
                  player doesn't own, the LOCK sits in the check's
                  seat instead — tapping it explains, in the note
                  line under the stage, why it can't be chosen. */}
              {fighterLocked ? (
                <ChooseLockButton
                  name={fighter.name}
                  onTap={() => setNote(lockReasonFor(fighter.name))}
                />
              ) : (
                <ChooseCheckButton
                  name={fighter.name}
                  element={fighter.element}
                  onChosen={() => triggerAction('choose')}
                />
              )}
            </Box>
            <Typography variant="body2" sx={{ color: '#9dbec9' }}>
              {fighter.element} · Lv. {fighter.level} · Bond {care.bond} · XP {care.xp}
            </Typography>
            {fighter.tag && (
              <Chip
                label={fighter.tag}
                size="small"
                sx={{ mt: 0.75, bgcolor: '#ffd54f', color: '#4a3500', fontWeight: 'bold' }}
              />
            )}
            {fighterIsChosen && (
              <Chip
                label="✓ CHOSEN — YOUR BATTLE NAVITAR"
                size="small"
                sx={{
                  mt: 0.75,
                  ml: fighter.tag ? 1 : 0,
                  bgcolor: '#ffd54f',
                  color: '#4a3500',
                  fontWeight: 900,
                  boxShadow: '0 0 14px rgba(255,213,79,0.7)',
                }}
              />
            )}
          </Box>
          <IconButton
            aria-label="Next navitar"
            onClick={() => goTo(index + 1)}
            sx={{ color: '#eaf6fa' }}
          >
            <ChevronRightIcon fontSize="large" />
          </IconButton>
        </Box>

        <div className="glacer-stage-floor" />
        {/* Elemental dripping background — the fighter's elemental
            weather across the stage band. Round 7 composition fix:
            the layer now sits ABOVE the model block (zIndex 3,
            pointer-events none) instead of behind it. Behind, the
            Round 6 podium disc — opaque, bright, element-tinted —
            ate the whole lower field: the wash and every drip that
            fell over the disc's span vanished into it, and the
            backdrop read as lost. Above, the disc stands WITHIN
            the weather (drips fall over its front face, embers
            rise past the fighter) and the full Round 1/4 field —
            22 particles + wash — is visible again. Nothing about
            the effect itself changed: same counts, same palette,
            same per-fighter keyed remount. */}
        <div
          style={{
            position: 'absolute',
            top: 64,
            bottom: 96,
            left: 0,
            right: 0,
            zIndex: 3,
            pointerEvents: 'none',
          }}
        >
          {/* Keyed per fighter (Eddie, 2026-11-16 regression
              check): keying on name+element forces a full remount
              on every roster move, so no particle from the previous
              fighter — in the previous element's colours — can
              survive into the new fighter's background. The
              component's particle field is also re-seeded from
              seed={fighter.name} + element colours in its useMemo,
              and the ambient shot/cry effects below already depend
              on fighter.name/fighter.element. */}
          <ElementalAmbience
            key={`${fighter.name}-${fighter.element}`}
            element={fighter.element}
            seed={fighter.name}
            variant="stage"
            active={ambientActive}
          />
        </div>
        {/* Model + lore row (Round 9): on wide screens the lore
            panel sits BESIDE the model; on phone the model keeps
            the full width and the lore rides the 📖 toggle +
            collapse below. The wrapper is the positioning context
            for the phone toggle pill. */}
        <Box
          sx={{
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            gap: { md: 2 },
            px: { md: 2 },
            position: 'relative',
            alignItems: { md: 'flex-start' },
          }}
        >
          <div
            className={`glacer-stage-model${motionClass ? ` ${motionClass}` : ''}${
              action?.source === 'choose' ? ' chosen-flash' : ''
            }${shot?.kind === 'lunge' && !action && !react ? ' amb-lunge' : ''}`}
            // The swipe gesture surface is the whole stage card
            // (Round 9 — handlers + the touch guard live on
            // .glacer-stage above; events from the model bubble up
            // to them). pan-y stays here so vertical page scroll
            // stays native on the model itself; horizontal drags
            // belong to the Stage gesture, never to the
            // model/camera — there is no orbit to fight with.
            style={{
              // In the lore row: the model takes the flexible share
              // on wide screens (full width on phone, where the row
              // stacks and the aside hides).
              flex: '1 1 auto',
              minWidth: 0,
              filter: care.tint,
              // The idle signature's own tempo + phase, only while
              // idling (the sigact/react keyframes carry their own
              // durations in CSS and must not be overridden).
              ...(!action && !react && ambientActive
                ? { animationDuration: `${sig.durationS}s`, animationDelay: `${sig.delayS}s` }
                : {}),
              // Chosen ring: an outline + glow on the model block
              // itself. (Round 7: the ambience weather layer rides
              // above the block at zIndex 3 — a few drips crossing
              // the ring read as atmosphere, same as over the disc.)
              position: 'relative',
              zIndex: 2,
              // Swipe surface: vertical drags scroll the page,
              // horizontal drags belong to the Stage gesture.
              touchAction: 'pan-y',
              borderRadius: 24,
              ...(fighterIsChosen
                ? {
                    outline: '3px solid #ffd54f',
                    outlineOffset: -3,
                    boxShadow:
                      '0 0 0 2px rgba(255,213,79,0.4), 0 0 32px rgba(255,213,79,0.55), inset 0 0 32px rgba(255,213,79,0.18)',
                  }
                : {}),
            }}
          >
            {modelFailedFor === fighter.name ? (
              // WebGL unavailable / model failed (2026-11-16 hardening):
              // the stage falls back to the fighter's 2D portrait —
              // never an empty box, never a dead page. ModelCanvas
              // already catches the renderer throw; this wires its
              // onError to an actual fallback (it used to be a no-op).
              <Box
                sx={{
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <NavitarArtImg
                  src={resolveNavitarArt(undefined, fighter.name) ?? ''}
                  alt={`${fighter.name} portrait`}
                  element={fighter.element}
                  fit="contain"
                  // Round 25: the Stage's ONE standard picture frame
                  // (same 78% / 5:7 frame the summon veil uses), so
                  // a fallback portrait renders at the same size the
                  // card and the model slot use.
                  style={{ height: '78%', maxWidth: '100%', aspectRatio: '5 / 7' }}
                />
              </Box>
            ) : (
              <>
                <ModelCanvas
                  key={fighter.name}
                  modelUrl={fighter.modelUrl}
                  zoom={fighter.modelZoom}
                  grounded
                  // Presentation law (Eddie, 2026-11-16): the model
                  // turns LEFT ↔ RIGHT in-scene — spin-signature
                  // fighters (Tidefang, Shadowmaw, Frostbite…) get
                  // the wide ±30° yaw at their signature tempo,
                  // everyone else a gentle ±12°. Always upright,
                  // never a full turn, no grab-and-orbit (the
                  // viewer has no orbit controls anymore).
                  yawAmpDeg={sig.style === 'spin' ? 30 : 12}
                  yawPeriodS={sig.style === 'spin' ? sig.durationS : Math.max(6, sig.durationS)}
                  yawPhaseS={sig.delayS}
                  // Standing base: element-tinted podium disc +
                  // contact shadow inside ModelCanvas (QC verified
                  // no model has a baked base — the disc applies to
                  // all). Water gets the ripple ring. Facing +
                  // seating come from the presentation registry:
                  // Leafblade turns −90° and Tidefang +90° to face
                  // the camera, and Tidefang's coil seats ~4% into
                  // its water disc.
                  baseTint={fx.primary}
                  ripple={fighter.element === 'water'}
                  rotationY={modelPresentationFor(fighter.modelUrl).rotationY}
                  sinkFrac={modelPresentationFor(fighter.modelUrl).sinkFrac}
                  onLoaded={() => setModelLoadedFor(fighter.name)}
                  onError={() => setModelFailedFor(fighter.name)}
                />
                {/* Loading veil (Round 6): while this fighter's GLB
                  is still travelling (they run up to ~28 MB), the
                  stage shows its portrait under a "summoning"
                  veil — the ModelViewer pattern. On load the
                  veil lifts ONCE and the 3D model stands there;
                  the two never flap back and forth.
                  Round 24: the veil's picture is now the fighter's
                  COLLECTIBLE CARD (SummonCard) when one exists —
                  the card loads first, the model swaps in. A
                  fighter without a card keeps the portrait veil
                  exactly as before. */}
                {modelLoadedFor !== fighter.name && (
                  <Box
                    sx={{
                      position: 'absolute',
                      inset: 0,
                      zIndex: 3,
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: 1.5,
                      pointerEvents: 'none',
                    }}
                  >
                    {getCollectibleCard(fighter.name) ? (
                      <SummonCard
                        name={fighter.name}
                        element={fighter.element}
                        style={{ height: '78%', maxWidth: '100%', aspectRatio: '5 / 7' }}
                      />
                    ) : (
                      <NavitarArtImg
                        src={resolveNavitarArt(undefined, fighter.name) ?? ''}
                        alt={`${fighter.name} portrait`}
                        element={fighter.element}
                        fit="contain"
                        // Round 25: identical frame to the SummonCard
                        // beside it (78% / 5:7) — the veil's picture is
                        // one standard size whichever art it shows.
                        style={{ height: '78%', maxWidth: '100%', aspectRatio: '5 / 7' }}
                      />
                    )}
                    <Box
                      sx={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1,
                        px: 1.5,
                        py: 0.5,
                        borderRadius: 999,
                        bgcolor: 'rgba(0,0,0,0.5)',
                        color: '#cfeef8',
                      }}
                    >
                      <CircularProgress size={16} sx={{ color: '#cfeef8' }} />
                      <Typography variant="body2">Summoning {fighter.name}…</Typography>
                    </Box>
                  </Box>
                )}
              </>
            )}
            {burst && (
              <div className="glacer-burst" style={{ color: elementColor(fighter.element) }}>
                {elementEmoji(fighter.element)}
              </div>
            )}
            {shot && shot.kind !== 'lunge' && (
              <div
                className="glacer-amb-shot"
                key={shot.key}
                style={{ color: fxColors(fighter.element).primary }}
              >
                {shot.kind === 'beam' ? (
                  <div
                    className="glacer-amb-beam"
                    style={{
                      background: `linear-gradient(90deg, ${fxColors(fighter.element).secondary}, ${
                        fxColors(fighter.element).primary
                      })`,
                      boxShadow: `0 0 18px ${fxColors(fighter.element).primary}`,
                    }}
                  />
                ) : shot.kind === 'burst' ? (
                  <div className="glacer-amb-ring" />
                ) : (
                  <div
                    className="glacer-amb-orb"
                    style={{
                      background: fxColors(fighter.element).primary,
                      boxShadow: `0 0 22px ${fxColors(fighter.element).primary}`,
                    }}
                  />
                )}
              </div>
            )}
            {/* SIGNATURE ACTION FX (Eddie, 2026-11-16): the elemental
              output while the fighter performs — fire breathes a
              beam of flame, ice breathes a frost cone, water jets,
              the burst-family answers with a ring + spray, shades
              and lights wash the stage in their colour. attackFx
              palette throughout; 6 spray orbs + one shape + one
              wash, far under the ≤40-particle law. */}
            {action && (
              <div className="glacer-sig-fx" key={action.key} style={{ color: fx.primary }}>
                {(action.kind === 'breath' || action.kind === 'jet') && (
                  <div
                    className="glacer-sig-beam"
                    style={{
                      background: `linear-gradient(90deg, ${fx.secondary}, ${fx.primary})`,
                      boxShadow: `0 0 28px ${fx.primary}`,
                    }}
                  />
                )}
                {action.kind === 'frostbreath' && (
                  <div
                    className="glacer-sig-cone"
                    style={{
                      background: `radial-gradient(closest-side at 0% 50%, ${fx.secondary}f2, ${fx.primary}8c 55%, transparent)`,
                    }}
                  />
                )}
                {(action.kind === 'bloom' ||
                  action.kind === 'wispflare' ||
                  action.kind === 'radiance' ||
                  action.kind === 'prism' ||
                  action.kind === 'flourish') && <div className="glacer-sig-ring" />}
                {(action.kind === 'radiance' || action.kind === 'wispflare') && (
                  <div
                    className="glacer-sig-wash"
                    style={{
                      background: `radial-gradient(60% 60% at 50% 45%, ${fx.primary}59, transparent 70%)`,
                    }}
                  />
                )}
                {SIG_ORBS.map((o, i) => (
                  <span
                    key={i}
                    className="glacer-sig-orb"
                    style={
                      {
                        width: Math.round(o.s * sig.amp),
                        height: Math.round(o.s * sig.amp),
                        background: i % 2 ? fx.primary : fx.secondary,
                        boxShadow: `0 0 14px ${fx.primary}`,
                        animationDelay: `${o.d}s`,
                        '--sig-dx': o.dx,
                        '--sig-dy': o.dy,
                      } as React.CSSProperties
                    }
                  />
                ))}
              </div>
            )}
          </div>
          {/* LORE, wide screens (Round 9): the staged fighter's
              real lore beside the model. Sits above the ambience
              weather (zIndex 4 over its 3) on a solid-enough
              backdrop that the text stays readable; height matches
              the model block's clamp and scrolls internally.
              Rendered only when this fighter HAS lore — see the
              `lore` note above. */}
          {lore && (
            <Box
              component="aside"
              aria-label={`${fighter.name} lore`}
              sx={{
                display: { xs: 'none', md: 'block' },
                width: 288,
                flexShrink: 0,
                height: 'clamp(230px, 34dvh, 340px)',
                overflowY: 'auto',
                position: 'relative',
                zIndex: 4,
                borderRadius: '20px',
                border: '1px solid var(--glacer-line)',
                background: 'rgba(6, 24, 33, 0.82)',
                p: 2,
              }}
            >
              <Typography
                variant="subtitle2"
                sx={{ color: '#ffd54f', fontWeight: 800, letterSpacing: '0.04em', mb: 0.75 }}
              >
                📖 {fighter.name}
              </Typography>
              <Typography variant="body2" sx={{ color: '#d7ecf3', lineHeight: 1.55 }}>
                {lore}
              </Typography>
            </Box>
          )}
          {/* LORE toggle, phone only (Round 9): an overlay pill on
              the model's top-left corner — zero vertical budget,
              so the Round 6 fit (full Stage + actions on screen)
              is untouched until the player chooses to open it. */}
          {lore && (
            <Button
              size="small"
              variant="contained"
              aria-expanded={loreOpen}
              aria-label={`Toggle lore for ${fighter.name}`}
              onClick={() => setLoreOpen(o => !o)}
              sx={{
                display: { xs: 'inline-flex', md: 'none' },
                position: 'absolute',
                top: 8,
                left: 8,
                zIndex: 5,
                borderRadius: 999,
                bgcolor: 'rgba(6, 24, 33, 0.72)',
                color: '#eaf6fa',
                '&:hover': { bgcolor: 'rgba(6, 24, 33, 0.92)' },
              }}
            >
              📖 Lore
            </Button>
          )}
        </Box>
        {/* LORE, phone (Round 9): collapsed by default behind the
            📖 pill above; opening it is the player's choice and
            the page scrolls — the default Stage fit is unchanged. */}
        {lore && (
          <Collapse in={loreOpen} sx={{ display: { md: 'none' } }}>
            <Paper sx={{ m: 2, p: 2 }}>
              <Typography
                variant="subtitle2"
                sx={{ color: '#ffd54f', fontWeight: 800, letterSpacing: '0.04em', mb: 0.75 }}
              >
                📖 {fighter.name}
              </Typography>
              <Typography variant="body2" sx={{ lineHeight: 1.55 }}>
                {lore}
              </Typography>
            </Paper>
          </Collapse>
        )}

        <Box
          sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap', px: 2, pb: 1 }}
        >
          <Button variant="contained" onClick={onModifyToggle}>
            ✨ Modify
          </Button>
          <Button variant="contained" color="success" onClick={onFeed}>
            🍖 Feed
          </Button>
          <Button
            variant="contained"
            color="secondary"
            onClick={() => setPanel(panel === 'bag' ? 'none' : 'bag')}
          >
            🎒 Bag
          </Button>
          <Button variant="contained" color="warning" onClick={onTrain} disabled={action !== null}>
            ⚡ Train{left > 0 ? ` (${left} left today)` : ' — resting'}
          </Button>
        </Box>
        <Box sx={{ px: 2, pb: 1.5, maxWidth: 420, mx: 'auto' }}>
          {/* Owned → the Choose button; unowned → the locked
              panel in the same slot (Round 16). BattleWithButton
              itself also renders nothing for an unowned fighter
              now, so the two guards agree by construction. */}
          {fighterLocked ? (
            <LockedChoosePanel name={fighter.name} />
          ) : (
            <BattleWithButton
              name={fighter.name}
              element={fighter.element}
              onChosen={() => triggerAction('choose')}
            />
          )}
        </Box>
        {note && (
          <Typography variant="body2" align="center" sx={{ color: '#cfeef8', pb: 1.5, px: 2 }}>
            {note}
          </Typography>
        )}

        <Collapse in={panel === 'modify'}>
          <Paper sx={{ m: 2, p: 2 }} data-noswipe="true">
            <Typography variant="subtitle1" gutterBottom>
              Modify {fighter.name}
            </Typography>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Crystal tint
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
              {TINTS.map(t => (
                <Chip
                  key={t.label}
                  label={t.label}
                  clickable
                  color={care.tint === t.filter ? 'primary' : 'default'}
                  onClick={() => {
                    setCare(updateCare(fighter.name, { tint: t.filter }));
                    triggerReact('pulse', false);
                  }}
                />
              ))}
            </Box>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Gear (tap to equip / remove)
            </Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              {GEAR.map(g => (
                <Chip
                  key={g}
                  label={g}
                  clickable
                  color={care.gear.includes(g) ? 'secondary' : 'default'}
                  onClick={() => toggleGear(g)}
                />
              ))}
            </Box>
          </Paper>
        </Collapse>
        <Collapse in={panel === 'bag'}>
          <Paper sx={{ m: 2, p: 2 }} data-noswipe="true">
            <Typography variant="subtitle1" gutterBottom>
              Your bag — give {fighter.name} something
            </Typography>
            <InventoryBagPanel
              onItemUsedOnNavitar={usedOn => {
                // An item landing on the STAGED fighter answers
                // with a glow pulse + sparkle (items used on other
                // fighters don't perform here).
                if (usedOn === fighter.name) triggerReact('pulse', true);
              }}
            />
          </Paper>
        </Collapse>
      </Box>

      <div className="glacer-stage-chips">
        {roster.map((f, i) => (
          <Chip
            key={f.name}
            label={`${userNavitar && ownedNavitars.some(n => n.id === userNavitar.id && n.name === f.name) ? '✓ ' : ''}${elementEmoji(f.element)} ${f.name}`}
            clickable
            color={i === index ? 'primary' : 'default'}
            onClick={() => goTo(i)}
          />
        ))}
      </div>
      <Typography variant="body2" color="text.secondary" align="center">
        Swipe the stage or tap a name to walk your roster. Training is once a day per navitar —
        twice a day from Lv. {TWICE_DAILY_LEVEL}. Every navitar moves in its own way, and every so
        often it shows off its signature — a fire dragon rears up and blows fire, an ice dragon
        breathes frost, a shade sinks into its wisps. The models are single-piece sculptures, so the
        stage lends them the motion; the personality is theirs.
      </Typography>
    </Box>
  );
};

export default NavidexStage;
