import { useEffect, useState } from 'react';

// Global 3D-model loading registry (Round 24, Eddie 2026-11-18).
// Every GLB load in the app — the Navidex Stage and card viewers
// (ModelCanvas), the battle arena (ElementalWorld) — registers
// here, so any surface can answer one question: is a model loading
// anywhere right now?
//
// Two consumers:
//  1. The ambient slowdown Eddie approved for the collectible-card
//     round: while a model is travelling, the background ambient
//     animations (ElementalAmbience particles, card idle motion)
//     ease off to a slower rate, and resume when the last load
//     lands. The counter (not a boolean) keeps overlapping loads
//     honest — the slowdown ends only when ALL of them finish.
//  2. Observability: the state is mirrored onto
//     document.documentElement.dataset.modelLoading so it can be
//     read from the DOM without reaching into React.
//
// Registration is begin/end paired by the loaders themselves;
// ModelCanvas also ends the registration on unmount, so a load
// abandoned mid-flight can never wedge the counter.

let activeLoads = 0;
const listeners = new Set<() => void>();

function emit() {
  if (typeof document !== 'undefined') {
    if (activeLoads > 0) document.documentElement.dataset.modelLoading = 'true';
    else delete document.documentElement.dataset.modelLoading;
  }
  listeners.forEach(l => l());
}

export function beginModelLoad(): void {
  activeLoads += 1;
  emit();
}

export function endModelLoad(): void {
  activeLoads = Math.max(0, activeLoads - 1);
  emit();
}

export function anyModelLoading(): boolean {
  return activeLoads > 0;
}

export function useAnyModelLoading(): boolean {
  const [loading, setLoading] = useState<boolean>(anyModelLoading);
  useEffect(() => {
    const listener = () => setLoading(anyModelLoading());
    listeners.add(listener);
    listener();
    return () => {
      listeners.delete(listener);
    };
  }, []);
  return loading;
}

// The ambient rate while a model loads: background animation
// durations stretch by this factor (ElementalAmbience particles
// and, via CSS in modern.css, the card idle signatures).
export const AMBIENT_LOAD_SLOWDOWN = 2.5;
