import React from 'react';
import { Box } from '@mui/material';
import { elementColor } from '../utils/navitarArt';
import { getCollectibleCard } from '../utils/collectibleCards';

// The SUMMON visual (Round 24, Eddie 2026-11-18): while a fighter's
// 3D model is still travelling (the GLBs run 20–28 MB), the slot
// shows the fighter's collectible card instead of a spinner over a
// portrait. The card is a light image (~150–250 KB), so it lands
// instantly even on a bad connection; when the model is ready the
// caller swaps it in — the two never flap back and forth, the swap
// happens once, on load.
//
// The card is shown WHOLE (objectFit contain — never cropped, per
// Eddie's never-crop law) on the element-tinted gradient the art
// slots already use, with a soft element glow breathing behind it
// while the summon is in flight. A fighter without a collectible
// card renders nothing here and the caller keeps its previous
// loading treatment — this component never invents art.
export const SummonCard: React.FC<{
  name: string;
  element: string;
  style?: React.CSSProperties;
}> = ({ name, element, style }) => {
  const src = getCollectibleCard(name);
  if (!src) return null;
  const color = elementColor(element);
  return (
    <Box
      data-summon-card={name}
      sx={{
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        overflow: 'hidden',
        background: `radial-gradient(circle at 50% 32%, ${color}55, var(--glacer-art-tile-end, #10151c) 78%)`,
        ...style,
      }}
    >
      <Box
        aria-hidden
        sx={{
          position: 'absolute',
          width: '62%',
          aspectRatio: '1',
          borderRadius: '50%',
          background: `radial-gradient(circle, ${color}66, transparent 70%)`,
          animation: 'glacer-summon-breathe 2.6s ease-in-out infinite',
          '@keyframes glacer-summon-breathe': {
            '0%, 100%': { transform: 'scale(0.92)', opacity: 0.55 },
            '50%': { transform: 'scale(1.08)', opacity: 0.95 },
          },
        }}
      />
      <img
        src={src}
        alt={`${name} collectible card`}
        style={{
          position: 'relative',
          maxWidth: '100%',
          maxHeight: '100%',
          width: 'auto',
          height: '100%',
          objectFit: 'contain',
          display: 'block',
          borderRadius: 10,
          boxShadow: `0 10px 34px rgba(0,0,0,0.55), 0 0 22px ${color}55`,
        }}
      />
    </Box>
  );
};

export default SummonCard;
